export function ofType<T extends ServerEvent["type"]>(events: ServerEvent[], type: T): Extract<ServerEvent, { type: T }>[] {
  return events.filter((e): e is Extract<ServerEvent, { type: T }> => e.type === type);
}

/** The events up to and including the first one `match` says yes to (a stream re-recorded with another count of events still cuts at the same moment). */
export function through(events: ServerEvent[], match: (e: ServerEvent) => boolean): ServerEvent[] {
  const i = events.findIndex(match);
  if (i < 0) throw new Error("no such event in the stream");
  return events.slice(0, i + 1);
}

export const stageEvent = (key: string, state: string) => (e: ServerEvent) => e.type === "stage" && e.data.key === key && e.data.state === state;
export const isQuestion = (e: ServerEvent) => e.type === "question";
